<script setup lang="ts">import type{UndoCheck}from'../../api/desktop';defineProps<{check:UndoCheck|null;busy:boolean}>();defineEmits(['execute'])</script><template><section class="check" v-loading="busy"><el-empty v-if="!check" description="从左侧选择一条操作并进行安全检查"/><template v-else><el-alert :type="check.safe?'success':'error'" :title="check.summary" :closable="false" show-icon/><div class="actions"><span>待检查 {{check.items.length}} 项</span><el-button type="primary" :disabled="!check.safe||busy" @click="$emit('execute')">确认整批撤回</el-button></div><el-table :data="check.items" height="390"><el-table-column label="安全" width="64"><template #default="p">{{p.row.safe?'✓':'!'}}</template></el-table-column><el-table-column prop="currentSource" label="当前路径" show-overflow-tooltip/><el-table-column prop="restoreTarget" label="恢复为" show-overflow-tooltip/><el-table-column prop="detail" label="说明" show-overflow-tooltip/></el-table></template></section></template><style scoped>.check{padding:18px;background:var(--surface);border:1px solid var(--border);border-radius:var(--radius)}.actions{display:flex;align-items:center;justify-content:space-between;padding:16px 0;color:var(--muted)}</style>
